import os
import textwrap
from tempfile import NamedTemporaryFile
from typing import Any, Dict, Optional, Tuple

import viktor as vkt

try:
    import ifcopenshell
    import ifcopenshell.util.element
except Exception:  # pragma: no cover
    ifcopenshell = None


def _to_float(value: Any) -> Optional[float]:
    if value is None:
        return None
    try:
        return float(value)
    except Exception:
        try:
            return float(str(value))
        except Exception:
            return None


def _safe_name(obj: Any) -> str:
    # Prefer LongName (common for storeys) and fall back to Name / GlobalId
    for attr in ("LongName", "Name"):
        val = getattr(obj, attr, None)
        if isinstance(val, str) and val.strip():
            return val.strip()
    gid = getattr(obj, "GlobalId", None)
    return gid or "(Unnamed)"


def _get_storey(product: Any) -> Optional[Any]:
    """Return the IfcBuildingStorey of a product.

    Many elements are contained in IfcSpace; we walk up the spatial containment chain
    until we find an IfcBuildingStorey.
    """
    if product is None or ifcopenshell is None:
        return None

    try:
        container = ifcopenshell.util.element.get_container(product)
    except Exception:
        container = None

    # Walk up spatial containment chain (Space -> Storey -> Building -> Site -> Project)
    visited = set()
    while container is not None and getattr(container, "id", None) and container.id() not in visited:
        visited.add(container.id())
        if container.is_a("IfcBuildingStorey"):
            return container
        try:
            container = ifcopenshell.util.element.get_container(container)
        except Exception:
            break
    return None


def _get_area_from_storey_qto(storey: Any) -> Optional[float]:
    """Try to read a storey area from quantities (if present in the IFC)."""
    if storey is None:
        return None
    try:
        psets = ifcopenshell.util.element.get_psets(storey)
    except Exception:
        return None

    qto = psets.get("Qto_BuildingStoreyBaseQuantities", {}) if isinstance(psets, dict) else {}
    for key in (
        "GrossFloorArea",
        "NetFloorArea",
        "GrossArea",
        "NetArea",
    ):
        val = _to_float(qto.get(key))
        if val is not None:
            return val
    return None


def _get_area_from_space(space: Any) -> Optional[float]:
    if space is None:
        return None
    try:
        psets = ifcopenshell.util.element.get_psets(space)
    except Exception:
        return None

    qto = psets.get("Qto_SpaceBaseQuantities", {}) if isinstance(psets, dict) else {}
    for key in (
        "NetFloorArea",
        "GrossFloorArea",
        "NetArea",
        "GrossArea",
    ):
        val = _to_float(qto.get(key))
        if val is not None:
            return val

    # Some authoring tools put areas in Pset_SpaceCommon / custom sets
    pset_common = psets.get("Pset_SpaceCommon", {}) if isinstance(psets, dict) else {}
    for key in ("GrossPlannedArea", "NetPlannedArea", "FloorArea"):
        val = _to_float(pset_common.get(key))
        if val is not None:
            return val

    return None


def _load_ifc_model_from_viktor_file(ifc_vkt_file: vkt.File) -> "ifcopenshell.file":
    if ifcopenshell is None:
        raise vkt.UserError(
            "The 'ifcopenshell' package is not available in this environment. "
            "Add it to requirements.txt (e.g. ifcopenshell==0.8.*)."
        )

    content = ifc_vkt_file.getvalue()
    if isinstance(content, str):
        content = content.encode("utf-8", errors="ignore")

    tmp_path = None
    try:
        with NamedTemporaryFile(suffix=".ifc", delete=False) as tmp:
            tmp.write(content)
            tmp_path = tmp.name

        model = ifcopenshell.open(tmp_path)
        return model
    except Exception as e:
        raise vkt.UserError(f"Could not open IFC file: {e}")
    finally:
        if tmp_path and os.path.exists(tmp_path):
            try:
                os.remove(tmp_path)
            except Exception:
                pass


class Parametrization(vkt.Parametrization):
    inputs = vkt.Section("IFC input")
    inputs.intro = vkt.Text(
        textwrap.dedent(
            """\
            # Element Count by Floor (IFC)

            Upload an IFC file and get a per-storey (floor) overview:

            - Number of elements per storey
            - Optional space count and floor area (if quantities are available)

            Notes:
            - Elements are assigned to floors via IFC spatial containment (e.g. `IfcRelContainedInSpatialStructure`).
            - Some models have elements assigned to **spaces**; this app will still map them up to the parent storey.
            """
        )
    )
    inputs.ifc_file = vkt.FileField("IFC file")

    settings = vkt.Section("Counting settings")
    settings.scope = vkt.OptionField(
        "Count scope",
        options=[
            "All IfcElement (recommended)",
            "IfcBuildingElement only",
        ],
        default="All IfcElement (recommended)",
    )
    settings.include_openings = vkt.BooleanField(
        "Include IfcOpeningElement in counts?",
        default=False,
        description="If disabled, opening elements are excluded (usually not useful for quantity planning).",
    )
    settings.include_unassigned = vkt.BooleanField(
        "Include a 'No storey' row for unassigned elements?",
        default=True,
    )

    area = vkt.Section("Floor area (optional)")
    area.calculate_area = vkt.BooleanField(
        "Calculate floor area (if present in IFC quantities)",
        default=True,
    )
    area.method = vkt.OptionField(
        "Area method",
        options=[
            "Auto (storey Qto else sum space areas)",
            "Storey quantities only (Qto_BuildingStoreyBaseQuantities)",
            "Sum of space areas only (Qto_SpaceBaseQuantities)",
        ],
        default="Auto (storey Qto else sum space areas)",
        visible=vkt.Lookup("area.calculate_area"),
    )


class Controller(vkt.Controller):
    label = "Element Count by Floor"
    parametrization = Parametrization

    def _get_counts_by_storey(self, params: Parametrization) -> Tuple[list, bool]:
        if params.inputs.ifc_file is None or params.inputs.ifc_file.file is None:
            return [], False

        model = _load_ifc_model_from_viktor_file(params.inputs.ifc_file.file)

        storeys = model.by_type("IfcBuildingStorey")
        storey_index: Dict[str, Dict[str, Any]] = {}

        for s in storeys:
            gid = getattr(s, "GlobalId", None) or str(s.id())
            storey_index[gid] = {
                "storey": s,
                "name": _safe_name(s),
                "elevation": _to_float(getattr(s, "Elevation", None)),
                "elements_total": 0,
                "elements_building": 0,
                "elements_distribution": 0,
                "elements_other": 0,
                "spaces": 0,
                "area": None,
            }

        no_storey_key = "__NO_STOREY__"
        if params.settings.include_unassigned:
            storey_index[no_storey_key] = {
                "storey": None,
                "name": "No storey (unassigned)",
                "elevation": None,
                "elements_total": 0,
                "elements_building": 0,
                "elements_distribution": 0,
                "elements_other": 0,
                "spaces": 0,
                "area": None,
            }

        # --- Element counting ---
        if params.settings.scope == "IfcBuildingElement only":
            elements = model.by_type("IfcBuildingElement")
        else:
            elements = model.by_type("IfcElement")

        for el in elements:
            if not params.settings.include_openings and el.is_a("IfcOpeningElement"):
                continue

            st = _get_storey(el)
            key = None
            if st is not None:
                key = getattr(st, "GlobalId", None) or str(st.id())

            if key not in storey_index:
                # Storey exists in file but not in our list (rare); create a row
                if st is not None:
                    storey_index[key] = {
                        "storey": st,
                        "name": _safe_name(st),
                        "elevation": _to_float(getattr(st, "Elevation", None)),
                        "elements_total": 0,
                        "elements_building": 0,
                        "elements_distribution": 0,
                        "elements_other": 0,
                        "spaces": 0,
                        "area": None,
                    }

            if key is None:
                if params.settings.include_unassigned:
                    key = no_storey_key
                else:
                    continue

            storey_index[key]["elements_total"] += 1
            if el.is_a("IfcBuildingElement"):
                storey_index[key]["elements_building"] += 1
            elif el.is_a("IfcDistributionElement"):
                storey_index[key]["elements_distribution"] += 1
            else:
                storey_index[key]["elements_other"] += 1

        # --- Spaces & floor area ---
        calculate_area = bool(params.area.calculate_area)
        area_method = params.area.method

        if calculate_area:
            # Initialize areas to 0 where relevant
            for info in storey_index.values():
                info["area"] = 0.0

            # First: storey Qto (if used)
            if area_method in (
                "Auto (storey Qto else sum space areas)",
                "Storey quantities only (Qto_BuildingStoreyBaseQuantities)",
            ):
                for info in storey_index.values():
                    st = info["storey"]
                    if st is None:
                        continue
                    a = _get_area_from_storey_qto(st)
                    if a is not None:
                        info["area"] = float(a)

            # Second: sum space areas (if used)
            if area_method in (
                "Auto (storey Qto else sum space areas)",
                "Sum of space areas only (Qto_SpaceBaseQuantities)",
            ):
                spaces = model.by_type("IfcSpace")
                for sp in spaces:
                    st = _get_storey(sp)
                    key = None
                    if st is not None:
                        key = getattr(st, "GlobalId", None) or str(st.id())

                    if key is None:
                        if params.settings.include_unassigned:
                            key = no_storey_key
                        else:
                            continue

                    if key not in storey_index:
                        # create row if missing
                        storey_index[key] = {
                            "storey": st,
                            "name": _safe_name(st) if st is not None else "No storey (unassigned)",
                            "elevation": _to_float(getattr(st, "Elevation", None)) if st is not None else None,
                            "elements_total": 0,
                            "elements_building": 0,
                            "elements_distribution": 0,
                            "elements_other": 0,
                            "spaces": 0,
                            "area": 0.0,
                        }

                    storey_index[key]["spaces"] += 1

                    # Only add space areas if:
                    # - area_method forces it, or
                    # - auto AND we don't already have a storey-qto area (area is still 0)
                    sp_area = _get_area_from_space(sp)
                    if sp_area is None:
                        continue

                    if area_method == "Sum of space areas only (Qto_SpaceBaseQuantities)":
                        storey_index[key]["area"] += float(sp_area)
                    else:
                        # Auto: only if no storey Qto was found (still 0)
                        if storey_index[key]["storey"] is not None and storey_index[key]["area"] == 0.0:
                            storey_index[key]["area"] += float(sp_area)
                        elif storey_index[key]["storey"] is None:
                            storey_index[key]["area"] += float(sp_area)

            # If a storey has no area, show blank instead of 0
            for info in storey_index.values():
                if info["storey"] is None:
                    continue
                if info["area"] == 0.0:
                    info["area"] = None

        # Sort storeys by elevation (if present) then name
        def sort_key(item: Dict[str, Any]):
            elev = item.get("elevation")
            return (
                1 if elev is None else 0,
                elev if elev is not None else 0.0,
                item.get("name") or "",
            )

        rows_out = []
        storey_rows = sorted(storey_index.values(), key=sort_key)

        for info in storey_rows:
            rows_out.append(
                [
                    info["name"],
                    info["elevation"],
                    info["elements_total"],
                    info["elements_building"],
                    info["elements_distribution"],
                    info["elements_other"],
                    info["spaces"],
                    info["area"],
                ]
            )

        return rows_out, calculate_area

    @vkt.TableView("Element count by floor", duration_guess=2)
    def element_count_by_floor(self, params: Parametrization, **kwargs):
        rows, calculate_area = self._get_counts_by_storey(params)

        if not rows:
            return vkt.TableResult(
                [["Upload an IFC file to see results", "", "", "", "", "", "", ""]],
                column_headers=[
                    "Storey",
                    "Elevation",
                    "Elements (total)",
                    "Building elements",
                    "Distribution (MEP)",
                    "Other elements",
                    "Spaces",
                    "Floor area",
                ],
            )

        headers = [
            "Storey",
            "Elevation [m]",
            "Elements (total)",
            "Building elements",
            "Distribution (MEP)",
            "Other elements",
            "Spaces",
            "Floor area [m²]" if calculate_area else "Floor area",
        ]

        return vkt.TableResult(rows, column_headers=headers)

    @vkt.IFCView("IFC model")
    def ifc_model(self, params: Parametrization, **kwargs):
        if params.inputs.ifc_file is None or params.inputs.ifc_file.file is None:
            raise vkt.UserError("Please upload an IFC file first.")
        return vkt.IFCResult(params.inputs.ifc_file.file)
